alter table public.questions drop constraint if exists questions_answer_check;

alter table public.questions add constraint questions_answer_check check (answer ~ '^[A-E](/[A-E])*$');

insert into public.exams (slug,title,source,year) values ('pism-ii-2025-dia-1','PISM II 2025 - 1º dia','pism','2025-1') on conflict (slug) do update set title=excluded.title, source=excluded.source, year=excluded.year;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 1, 'Língua Portuguesa', 'Projeto de Lei (PL) é um gênero de texto que objetiva elaborar uma proposta com normas que regulamentem a sociedade brasileira. Este, depois de lido e discutido, passa por uma votação, podendo ser aprovado (com ou sem modificações) ou recusado. Dentre as características estruturantes de um PL, há', 'Texto I: Projeto de Lei nº 2347/2022, do deputado José Nelto. O projeto propõe regulamentar a atividade de influenciador digital, descreve suas atribuições em artigos, prevê direitos e deveres e apresenta uma justificativa para a regulamentação.', null, '["apresentação de estratégias discursivas de aumento de credibilidade, como citação de autoridade e de dados estatísticos, por se tratar de um gênero da tipologia expositiva que visa, portanto, explicar determinado conteúdo.", "escrita em tópicos, indicando os artigos, de modo que os objetivos do PL, os direitos e os deveres dos envolvidos e a maneira da efetiva regulamentação da lei proposta estejam claros e de fácil compreensão e localização.", "presença de título chamativo, de modo que prenda a atenção do leitor e o faça ter curiosidade para continuar a leitura do texto, o qual apresenta seu objetivo na última seção, isto é, no desfecho.", "uso de linguagem subjetiva e indireta, uma vez que textos da esfera normativa são de leituras pouco comuns à sociedade em geral, sendo sua circulação restrita aos órgãos públicos.", "uso de verbos no presente do indicativo, pois este gênero pretende descrever um cenário brasileiro e mundial – o aumento considerável do número de influenciadores digitais –, fundamentado com argumentos."]'::jsonb, 'B', 'Alternativa B. Um projeto de lei organiza as normas em artigos e incisos, permitindo localizar as atribuições, os direitos, os deveres e as condições de aplicação da proposta. Sua finalidade normativa exige clareza e organização. As demais alternativas atribuem ao gênero características inadequadas, como subjetividade, apresentação do objetivo apenas no desfecho ou finalidade exclusivamente expositiva.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 2, 'Língua Portuguesa', 'Releia o trecho destacado do Texto I: “(...) Por existirem normas que regulamentam determinada profissão, nunca haverá dificuldade para identificar se um cidadão pode (ou deve) ser qualificado como profissional de determinada área (...)”. Qual alternativa apresenta análise CORRETA acerca da utilização dos verbos modais destacados?', 'Texto II: a modalidade expressa avaliações do falante sobre possibilidade ou necessidade. Verbos como poder, dever, ter que e precisar podem expressar essas avaliações. Consulte o Texto I no caderno oficial.', null, '["O uso do verbo modal “deve” entre parênteses indica que nem todos os que quiserem se cadastrar em determinada profissão serão aprovados, visto a necessidade de se adequarem aos critérios estabelecidos na lei.", "O uso do verbo modal “pode” explicita a obrigatoriedade do profissional ser graduado em tecnologias digitais para poder atuar como influenciador digital, uma vez que ele trabalhará em redes sociais.", "O uso dos verbos modais “pode” e “deve” faz referência à necessidade de o PL ser aprovado para que seja avaliado quem tem a possibilidade e quem tem o dever de atuar como influenciador digital.", "Os verbos modais “pode” e “deve” têm forças argumentativas opostas, pois o primeiro trata de uma ordem e o segundo de um aconselhamento para o cidadão, que pode ser um profissional qualificado ou não.", "Os verbos modais “pode” e “deve” têm forças argumentativas parecidas, pois ambos dão a ideia de uma sugestão para que o cidadão seja um profissional qualificado em redes sociais."]'::jsonb, 'A', 'Alternativa A. No trecho, poder indica possibilidade de alguém ser qualificado como profissional, enquanto dever introduz a exigência de cumprir os critérios que regulamentam a atividade. O emprego de dever entre parênteses reforça que essa qualificação depende das condições legais, e não apenas da vontade de se cadastrar. O trecho não exige especificamente graduação em tecnologias digitais.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 3, 'Língua Portuguesa', 'Em qual alternativa a seguir nota-se a NÃO neutralidade presente na notícia lida acerca da proposição do PL de regulamentação da profissão de Influenciador Digital?', 'Texto III: notícia de Marina Teodoro, publicada em 16/09/2022, sobre a proposta de regulamentação dos influenciadores digitais. A questão pede identificar o trecho em que aparece uma avaliação da jornalista.', null, '["“(...) também deverá ser solicitado “conhecimento técnico” para que os profissionais possam falar sobre determinados assuntos”.", "“O Brasil tem mais de 500 mil influenciadores digitais de acordo com levantamento da Nielsen”.", "“O PL ainda não avançou, e talvez não vá muito adiante: ele pode ser interpretado como inconstitucional”.", "“Se o PL passar, algumas exigências serão feitas para quem quiser virar influenciador”.", "(...) “um Projeto de Lei apresentado (...) pretende regulamentar essa categoria como profissão”."]'::jsonb, 'C', 'Alternativa C. A expressão talvez não vá muito adiante introduz uma previsão e uma avaliação da autora sobre o futuro do projeto. Isso evidencia uma posição na notícia, diferentemente dos trechos que informam números ou relatam a apresentação e as possíveis exigências do PL. A questão pede o trecho em que a neutralidade é rompida.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 4, 'Língua Portuguesa', 'Embora sejam de uma mesma temática – redes sociais e profissões – os textos I, III e IV se diferenciam quanto aos gêneros textuais e, portanto, quanto aos diferentes graus de parcialidade e imparcialidade, já que:', 'Texto I: projeto de lei. Texto III: notícia. Texto IV: postagem de @contente.vc que questiona a pressão para profissionais também produzirem conteúdo em redes sociais. O post solicita relatos dos seguidores e critica a sobrecarga desse trabalho adicional.', null, '["apesar de o texto IV solicitar aos leitores os dois pontos da questão levantada, há defesa de posicionamento em “a gente sabe que a cultura de trabalho não vai nada bem” e pretende-se que as respostas dos seguidores confirmem essa opinião.", "há defesa de ponto de vista no texto I, uma vez que o deputado que propôs o PL posiciona-se acerca da nova profissão de influenciador digital e pretende explicitar aos leitores os pontos positivos e negativos de exercer essa função.", "há defesa de ponto de vista no texto III, pois a jornalista argumenta contrariamente ao PL proposto, ao apresentar os impactos negativos para a economia brasileira caso se regulamente essa nova profissão.", "o texto I é imparcial, na medida em que seu objetivo é descrever as etapas de criação de uma lei – definindo a profissão de influenciador digital –, portanto não há defesa de um ponto de vista.", "por ser um post de rede social, o texto IV não apresenta defesa de ponto de vista, já que o seu objetivo é levantar a opinião dos leitores. Isso é reforçado pelas perguntas no início do texto, que instigam a participação do público-alvo."]'::jsonb, 'A', 'Alternativa A. Embora o post solicite opiniões, a crítica à cultura de trabalho já expressa um posicionamento contra a sobrecarga de conciliar a profissão com a produção de conteúdo. Fazer perguntas ao público não torna o texto automaticamente imparcial. Além disso, a justificativa de um projeto de lei também pode defender sua aprovação; gêneros diferentes usam estratégias e graus de posicionamento diferentes.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 5, 'Língua Portuguesa', 'Embora de pequena extensão, o gênero textual “comentário”pode ser produzido com a intenção de emitir ponto de vista sobre uma questão, apresentando argumentos que sustentem o posicionamento defendido. Sobre estratégias argumentativas utilizadas nos comentários ao lado, textos V, VI, VII e VIII, está CORRETO o que se afirma em:', 'Comentários V a VIII da postagem de @contente.vc: consulte as imagens na página 5 do caderno oficial. A questão compara as estratégias usadas para defender pontos de vista sobre divulgação profissional em redes sociais.', null, '["no texto VI, há uma defesa das postagens profissionais em redes sociais, pois é através dela que a comentarista relata ter conseguido avançar na carreira, bem como no texto V, que exalta a dinamicidade dos meios de divulgação atuais na medida em que permitem vender trabalhando em casa.", "o texto V e VII se aproximam, pois defende-se que as redes sociais democratizaram o marketing profissional, na medida em que tornaram gratuito o que antes era pago. Para fundamentar, foi feita uma alusão histórica e apresentado um exemplo de meios de divulgação que não os da rede social.", "o texto VIII discorda do que é levantado na legenda do post – “(...) mas quando isso vira uma obrigação (...), se transforma em sobrecarga” -, visto que sua argumentação está relacionada à falta de qualidade dos trabalhos divulgados em redes sociais, e não à qualidade de vida do profissional.", "os textos V, VI, VII e VIII apresentam relatos pessoais para fundamentar a opinião de que, embora representem um aumento na carga de trabalho, é fundamental a divulgação das profissões em redes sociais, o que indica um avanço do marketing atual em relação aos anteriores a esse recurso.", "os textos VI e VII seguem a mesma linha de argumentação para fundamentar suas teses, pois defendem a necessidade e a importância da divulgação do trabalho em redes sociais, atividade comercial que sempre foi feita, mas em outros meios não digitais."]'::jsonb, 'B', 'Alternativa B. Os comentários V e VII aproximam-se ao argumentar que as redes sociais ampliaram o acesso à divulgação profissional e reduziram custos que antes eram pagos. A comparação com práticas anteriores de publicidade constitui uma alusão histórica; mencionar outros meios de divulgação funciona como exemplo para sustentar a tese. A análise depende dos comentários no caderno oficial, e não apenas da legenda do post.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 6, 'Geografia', 'Em Maceió, a extração de sal-gema provocou o afundamento do solo e a remoção de milhares de moradores. Esse desastre, assim como os rompimentos de barragens em Mariana e Brumadinho, relaciona-se à atividade mineral. Do ponto de vista econômico, esses desastres estão associados a qual processo?', null, null, '["à emergência de novos distritos industriais no Brasil, em regiões até então pouco industriais.", "à reprimarização da economia brasileira, com aumento da importância do papel de setores como o de mineração.", "ao salto tecnológico da indústria brasileira, com alta demanda de minerais estratégicos associados à indústria 4.0.", "à crise no preço das commodities minerais, com retração da atividade em municípios tradicionalmente produtores de minérios.", "à integração dos blocos econômicos como o Mercosul, no qual cabe ao Brasil suprir a demanda sul-americana de minérios em geral."]'::jsonb, 'B', 'Alternativa B. Reprimarização é o aumento da importância de atividades ligadas à produção e à exportação de produtos primários, como minérios e produtos agropecuários, em relação a setores de maior transformação industrial. A expansão da extração mineral pode intensificar riscos sociais e ambientais quando faltam medidas adequadas de prevenção e controle. A alternativa relaciona os desastres citados à maior centralidade econômica da mineração.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 7, 'Geografia', 'Entre 2010 e 2022, municípios brasileiros com 100 mil a 499 mil habitantes concentraram 67,5% do crescimento populacional do país. Observe o gráfico. O crescimento populacional das cidades médias no Brasil é explicado pela:', null, '/pism-ii-2025-dia-1-questao-7.png', '["interiorização da economia.", "maior concentração industrial na Região Sudeste.", "maior capacidade de atração dos pequenos centros urbanos.", "proximidade entre as cidades médias e as capitais estaduais.", "maior concentração de cidades médias na porção litorânea do Brasil."]'::jsonb, 'A', 'Alternativa A. A interiorização da economia distribui atividades industriais, comerciais e de serviços para além das grandes metrópoles. Cidades médias passam a oferecer empregos, infraestrutura e serviços e atraem população. Isso explica seu crescimento, sem exigir que estejam no litoral, no Sudeste ou próximas de capitais. O gráfico mostra que o crescimento não se concentrou somente nas maiores cidades.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 8, 'Geografia', 'Analise o gráfico a seguir: Fonte: Censo Agropecuário (1980, 1985, 1995, 2006, 2017); Pesquisa Agrícola Municipal (PAM). Segundo dados do Instituto Brasileiro de Geografia e Estatística (IBGE), o setor agropecuário respondeu por 7,66% do Valor Adicionado Bruto (VAB) da economia brasileira em 2021. Neste setor, destaca-se a soja em grão, cuja participação foi de 41,61% do valor agropecuário total produzido no mesmo ano. Com base nestas informações e no gráfico acima, é CORRETO afirmar que a diminuição do número de pessoal ocupado em estabelecimentos rurais no Brasil entre 1980 e 2017 se deve', null, '/pism-ii-2025-dia-1-questao-8.png', '["ao decrescimento demográfico no país.", "à baixa disponibilidade de mão de obra no meio rural no Brasil.", "ao implemento de benefícios sociais e o aumento do número de aposentadorias.", "ao alto grau de mecanização e informatização alcançado pelo setor agropecuário.", "à capacidade limitada de absorção de mão de obra dos pequenos estabelecimentos."]'::jsonb, 'D', 'Alternativa D. Máquinas, mecanização e tecnologias de informação aumentam a produtividade agrícola e reduzem a quantidade de trabalhadores necessária para determinadas tarefas. Por isso, a produção pode crescer enquanto o número de pessoas ocupadas nos estabelecimentos rurais diminui, como indica o gráfico. Essa combinação não é explicada por uma redução geral da população brasileira.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 9, 'Geografia', 'O Censo 2022 registrou cerca de 11,4 milhões de domicílios vagos no Brasil, enquanto o déficit habitacional estimado para 2019 era de aproximadamente 5,9 milhões. Entre outros fatores, a coexistência de imóveis vazios e famílias sem habitação se deve:', null, null, '["à forte integração entre setor imobiliário e financeiro, encarecendo o preço dos imóveis e aluguéis.", "aos novos valores culturais da sociedade brasileira que levam as famílias a se organizarem em domicílios pluri-familiares.", "à expansão urbana desenfreada sobre zonas pouco atrativas da cidade, como aterramentos e áreas sujeitas a inundações.", "à crise no setor imobiliário e da construção civil que gerou um saldo de empresas falidas e imóveis abandonados e/ou inacabados.", "ao fenômeno da metropolização, que leva as famílias a buscarem as metrópoles e abandonar seus domicílios originais nas cidades médias."]'::jsonb, 'A', 'Alternativa A. A integração do mercado imobiliário com o setor financeiro transforma imóveis também em ativos de investimento e valorização. Preços e aluguéis elevados dificultam o acesso à moradia, enquanto parte dos imóveis permanece desocupada. Assim, a existência de muitas unidades vazias não garante que as famílias sem habitação consigam adquiri-las ou alugá-las.' from public.exams where slug='pism-ii-2025-dia-1'

