insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 10, 'Geografia', 'Pela primeira vez na história do país, o Censo 2022 investigou a população quilombola e suas características demográficas, geográficas e socioeconômicas, obtendo informações fundamentais para aprofundar o conhecimento e orientar políticas públicas. Fonte: Censo de 2022 – IBGE Adaptado de https://encurtador.com.br/r9bIC Acesso em 26 de jun. de 2024. O padrão da pirâmide etária ilustrada indica', null, '/pism-ii-2025-dia-1-questao-10.png', '["o predomínio da população masculina entre os quilombolas.", "o aumento da expectativa de vida da população quilombola.", "que predomina a população feminina quilombola a partir dos 50 anos de idade.", "que o índice de envelhecimento dos quilombolas é superior ao do total da população.", "que o perfil etário da população quilombola é mais jovem do que o do total da população."]'::jsonb, 'E', 'Alternativa E. Compare a área preenchida da população quilombola com o contorno da população brasileira: a população quilombola tem maior participação relativa nas faixas jovens e menor participação nas faixas mais idosas. Isso indica um perfil etário mais jovem e um menor envelhecimento relativo. Um único retrato da pirâmide não demonstra, por si só, aumento da expectativa de vida ao longo do tempo.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Matemática', 'De acordo com a Pesquisa Nacional por Amostragem de Domicílios (PNAD) divulgada pelo IBGE em abril de 2024, a proporção da população brasileira com algum tipo de rendimento alcançou seu pico histórico em 2023 atingindo 64,9% da população – aproximadamente 140 milhões de pessoas – frente à marca de 62,6% da população – aproximadamente 134 milhões de pessoas – no ano de 2022. O gráfico de barras abaixo apresenta o rendimento mensal médio da população residente com algum tipo de rendimento nos anos de 2022 e 2023 para cada uma das regiões brasileiras. Disponível em www.g1.globo.com/economia. Acesso em: 19 abr. 2024(adaptado). A região brasileira que apresentou o maior crescimento relativo do rendimento mensal médio da população residente com algum tipo de rendimento, de 2022 para 2023, é a', null, '/pism-ii-2025-dia-1-questao-11.png', '["Centro-Oeste.", "Nordeste.", "Norte.", "Sudeste.", "Sul."]'::jsonb, 'C', 'Alternativa C. Crescimento relativo = (valor de 2023 − valor de 2022) / valor de 2022 × 100. Norte: (2255 − 2052)/2052 × 100 ≈ 9,89%; Centro-Oeste: 8,61%; Sudeste: 8,18%; Nordeste: 5,43%; Sul: 5,25%. Portanto, o Norte apresentou a maior taxa percentual. Comparar apenas o aumento em reais levaria a uma conclusão diferente: o Centro-Oeste teve o maior aumento absoluto, mas não o relativo.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 12, 'Matemática', 'Lionel usa um filtro de coador de café cujo formato é o de um cone reto com base circular de altura 10 cm e com diâmetro da base igual a 12 cm. Ao preparar o café, o pó de café se dispõe sobre o coador formando um cone reto sólido com base circular paralela à base do coador ocupando-o até a metade de sua altura. A figura abaixo apresenta uma seção plana do coador que ilustra o pó de café no coador. A densidade do pó de café utilizado por Lionel é de 0,4 g/cm³ . Utilize 3 como aproximação para π. A quantidade, em gramas, de pó utilizado no preparo de café é igual a', null, '/pism-ii-2025-dia-1-questao-12.png', '["72", "54", "50", "48", "18"]'::jsonb, 'E', 'Alternativa E. O coador tem altura 10 cm e raio 6 cm. Como o pó ocupa metade da altura, o cone formado pelo pó tem altura 5 cm e, por semelhança, raio 3 cm. Seu volume é V = πr²h/3 = 3 × 3² × 5/3 = 45 cm³. A massa é m = densidade × volume = 0,4 × 45 = 18 g. O volume do cone menor corresponde a 1/8 do volume do cone completo.' from public.exams where slug='pism-ii-2025-dia-1'

