insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 13, 'Matemática', 'O quadro abaixo apresenta o preço médio, em reais, pago por uma saca de 60 Kg de café arábica no estado de São Paulo durante o ano de 2023. Mês Preço da saca (R$) Janeiro 1 000,00 Abril 1 100,00 Julho 1 000,00 Outubro 900,00 Disponível em: www.cepea.esalq.usp.br. Acesso em: 10 jul. 2024 (adaptado). Representando os meses de janeiro a dezembro por um parâmetro numérico x, que assume os valores inteiros de 1 a 12, sendo 1 para o mês de janeiro e 12 para o mês de dezembro, buscou-se representar, em 2023, o preço médio da saca por uma função P(x) em função do mês descrito pela variável numérica x, considerando que esses preços variam periodicamente, de forma contínua. Uma expressão que pode descrever a função P(x) é', null, null, '["100 + 1000 cos((πx − π)/12)", "1000 + 100 sen((πx − π)/6)", "100 + 1000 cos((πx − π)/6)", "1000 + 100 sen((πx − π)/12)", "1000 + 100 cos((πx − π)/12)"]'::jsonb, 'B', 'Alternativa B. A função precisa oscilar em torno de R$ 1000, com amplitude R$ 100. Em janeiro (x = 1), abril (x = 4), julho (x = 7) e outubro (x = 10), a expressão P(x) = 1000 + 100 sen(π(x − 1)/6) assume, respectivamente, 1000, 1100, 1000 e 900. O período é 12 meses, pois o coeficiente de x é π/6. Essas verificações correspondem à alternativa B.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 14, 'Matemática', 'Uma zona esférica é a parte da superfície esférica situada entre dois planos paralelos que a intersectam. Se a esfera tem raio R e a distância entre os planos é h então a área da zona esférica correspondente é igual a 2π · R · h. Um artesão modelou um vaso cuja parede lateral tem o formato de uma zona esférica, obtida a partir de uma esfera de raio 5 cm, de maneira que a abertura circular do vaso possui diâmetro interno medindo 8 cm e, a base circular, diâmetro interno medindo 6 cm. A figura abaixo apresenta uma seção do vaso. A área total da superfície interna desse vaso mede, em centímetros quadrados,', null, '/pism-ii-2025-dia-1-questao-14.png', '["96π", "95π", "80π", "79π", "70π"]'::jsonb, 'D', 'Alternativa D. O raio da esfera é 5 cm. A abertura tem raio 4 cm, portanto seu plano está a √(5² − 4²) = 3 cm do centro. A base tem raio 3 cm, e seu plano está a √(5² − 3²) = 4 cm do centro. Pelo desenho, os planos estão em lados opostos do centro: h = 3 + 4 = 7 cm. A área lateral interna é 2πRh = 70π; somando a base circular, de área 9π, obtém-se 79π cm². A abertura superior não é uma superfície fechada.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Matemática', 'O gráfico de colunas abaixo apresenta a distribuição das quantidades de cartões amarelos e cartões vermelhos que os jogadores de um time de futebol receberam nas primeiras dez rodadas de um campeonato. Represente por M1 a média de cartões amarelos recebidos pelos jogadores desse time, por rodada desse campeonato, e por M2 e M3, respectivamente, a mediana e a moda da distribuição das quantidades de cartões amarelos recebidos pelos jogadores desse time nas dez primeiras rodadas desse campeonato. Ordenando M1, M2 e M3 obtém-se', null, '/pism-ii-2025-dia-1-questao-15.png', '["M1 < M2 < M3", "M1 < M3 < M2", "M2 < M1 < M3", "M3 < M1 < M2", "M3 < M2 < M1"]'::jsonb, 'A', 'Alternativa A. Considere apenas as barras pretas, que representam cartões amarelos. As dez quantidades são 3, 4, 0, 3, 2, 1, 3, 4, 1 e 2. Média M1 = 23/10 = 2,3. Em ordem: 0, 1, 1, 2, 2, 3, 3, 3, 4, 4; mediana M2 = (2 + 3)/2 = 2,5. A moda M3 é 3, que aparece três vezes. Logo, M1 < M2 < M3. A terceira rodada conta com zero cartão amarelo.' from public.exams where slug='pism-ii-2025-dia-1'

