insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'Química', 'Nos materiais contendo ferro, não é difícil identificar que ocorreu a oxidação. A esponja de aço, por exemplo, ao entrar em contato com o hipoclorito de sódio (NaClO), conhecido como água sanitária, reage formando Fe₂O₃(s). A equação química, não balanceada, que representa a reação entre o ferro e o hipoclorito de sódio está representada a seguir: Fe(s) + NaClO(aq) → Fe₂O₃(s) + NaCl(aq) Quantos mols de NaClO são necessários para produzir 480 g de Fe₂O₃?', 'Para esta reação, use as massas molares aproximadas: Fe = 56 g/mol; O = 16 g/mol. Logo, Fe₂O₃ = 160 g/mol. A tabela periódica está no final do caderno oficial.', null, '["1", "2", "3", "6", "9"]'::jsonb, 'E', 'Alternativa E. Balanceando a reação: 2 Fe + 3 NaClO → Fe₂O₃ + 3 NaCl. A massa molar de Fe₂O₃ é 2 × 56 + 3 × 16 = 160 g/mol. Assim, 480 g correspondem a 480/160 = 3 mol de Fe₂O₃. Como cada mol de Fe₂O₃ exige 3 mol de NaClO, são necessários 3 × 3 = 9 mol de NaClO.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'Química', 'O gráfico abaixo apresenta a variação do coeficiente de solubilidade do nitrato de potássio (KNO3) em água. De acordo com sua interpretação do gráfico, marque a alternativa CORRETA.', null, '/pism-ii-2025-dia-1-questao-17.png', '["Ao prepararmos uma mistura contendo 80 g de KNO3 em 100 g de água na temperatura de 80 °C ela passará a ser saturada quando resfriada até 55 °C.", "Ao adicionarmos 80 g de KNO3 em 100 g de água na temperatura de 10 °C, apenas 60 g de KNO3 estarão dissolvidos em água.", "Ao prepararmos uma mistura de 150 g de KNO3 em 150 g de água na temperatura de 80 °C, observaremos o aparecimento de sólido quando essa mistura for aquecida para 90 °C.", "É possível dissolver totalmente 200 g de nitrato de potássio em 50 g de água na temperatura de 90 °C.", "Para preparar uma solução aquosa saturada de KNO3 na temperatura de 70 °C, deve-se adicionar 70 g de KNO3 em 50 g de água."]'::jsonb, 'E', 'Alternativa E. No gráfico, a solubilidade a 70 °C é aproximadamente 140 g de KNO₃ para cada 100 g de água. Para 50 g de água, a massa necessária para saturação é metade: 70 g. Aumentar a temperatura aumenta a solubilidade nessa curva; portanto, aquecer uma mistura não produz o precipitado descrito em C. Em D, 200 g em 50 g de água equivalem a 400 g em 100 g de água, acima da solubilidade indicada a 90 °C.' from public.exams where slug='pism-ii-2025-dia-1'

