insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'Química', 'O flúor, cloro, bromo e iodo pertencem ao grupo 17 da tabela periódica, também chamado de família dos halogênios. Esse grupo é um dos mais estudados na tabela periódica e geralmente fazem ligações covalentes simples ou se apresentam carregados negativamente. Alguns exemplos de substâncias que contêm halogênios em sua estrutura são: HCl, CaF2, CH3Br, I2, e NaClO. A alternativa que contém substâncias que apresentam ligações iônicas é:', null, null, '["CaF2 e NaClO.", "HCl e CaF2.", "HCl e NaClO.", "CH3Br e I2.", "HCl, CaF2 e CH3Br."]'::jsonb, 'A', 'Alternativa A. CaF₂ é formado por Ca²⁺ e F⁻; NaClO é formado por Na⁺ e pelo ânion poliatômico ClO⁻. Assim, ambos apresentam ligação iônica entre cátion e ânion. Dentro de ClO⁻ também há ligação covalente, mas isso não elimina o caráter iônico do composto. HCl, CH₃Br e I₂ são substâncias moleculares com ligações covalentes.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 19, 'Química', 'A palavra colágeno diz respeito a um grupo de 28 proteínas que são classificadas de acordo com o tipo de tecido em que estão presentes em maior concentração. Um dos compostos que compõe esse grupo de proteínas é a hidroxilisina, cuja fórmula está mostrada a seguir. O nome sistemático, seguindo as regras da IUPAC, para a hidroxilisina é', null, '/pism-ii-2025-dia-1-questao-19.png', '["ácido 2,6-diamino-5-hidroxihexanóico.", "ácido carboxilíco 2,6-diamino-5-hidroxi.", "2-amino-5-hidroxi-6-amino ácido hexanóico.", "2,6-diamino-5-hidroxi hexanóico.", "2-ácido-5-hidroxi-hexanodiamina."]'::jsonb, 'A', 'Alternativa A. A função principal é o ácido carboxílico; a cadeia principal tem seis carbonos e recebe o nome ácido hexanoico. A numeração começa no carbono da carboxila. Há grupos amino nos carbonos 2 e 6 e um grupo hidroxila no carbono 5. Portanto, o nome é ácido 2,6-diamino-5-hidroxihexanoico. As outras opções omitem partes do nome, posições ou a identificação adequada da cadeia.' from public.exams where slug='pism-ii-2025-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 20, 'Química', 'O oxigênio dissolvido na água, responsável pela manutenção da vida aquática, é de extrema importância no equilíbrio do ecossistema marítimo. Por exemplo, nas águas frias do Atlântico Norte existe maior atividade pesqueira do que nas águas quentes equatoriais, devido à maior abundância de vida marinha, já que as baixas temperaturas favorecem a interação entre as moléculas de oxigênio e as moléculas de água. Considere as interações intermoleculares abaixo: I. Interação entre moléculas de O2. II. Interação entre moléculas de H2O. III. Interação entre moléculas de O2 e H2O. Pode-se dizer que nos sistemas I, II e III as interações intermoleculares mais fortes presentes são, respectivamente, do tipo', null, null, '["I. dipolo induzido – dipolo induzido; II. ligação de hidrogênio; III. dipolo induzido – dipolo induzido.", "I. dipolo – dipolo; II. ligação de hidrogênio; III. dipolo induzido – dipolo induzido.", "I. dipolo – dipolo induzido; II. ligação de hidrogênio; III. dipolo-dipolo.", "I. dipolo induzido – dipolo induzido; II. ligação de hidrogênio; III. dipolo-dipolo induzido.", "I. dipolo induzido – dipolo induzido; II. ligação de hidrogênio; III. dipolo – dipolo."]'::jsonb, 'D', 'Alternativa D. O₂ é apolar: entre suas moléculas predominam forças de dispersão, também descritas como dipolo induzido–dipolo induzido. H₂O é polar e suas moléculas podem formar ligações de hidrogênio. Entre O₂ e H₂O, o dipolo permanente da água polariza a molécula de oxigênio: dipolo–dipolo induzido. É importante distinguir a ligação O–O dentro da molécula das interações entre moléculas.' from public.exams where slug='pism-ii-2025-dia-1'

