insert into public.exams (slug,title,source,year) values ('pism-ii-2025-dia-2','PISM II 2025 - 2º dia','pism','2025-2') on conflict (slug) do update set title=excluded.title, source=excluded.source, year=excluded.year;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 1, 'Literaturas', 'Em março de 1969, o poeta Carlos Drummond de Andrade traduziu algumas canções da banda inglesa The Beatles, do então recém lançado Álbum Branco. Dentre as canções, escreveu o poema "Melro", uma tradução da composição dos Beatles, cujo título original é "Blackbird" (pássaro preto - outro possível sinônimo de Melro, em língua portuguesa). Essa canção composta pela banda britânica teria como motivação a luta do Movimento dos Direitos Civis dos Negros, nos Estados Unidos. A partir da leitura do poema de Drummond e considerando as informações acima, assinale a alternativa que melhor interprete os versos lidos:', 'Texto I: Melro, tradução de Blackbird feita por Carlos Drummond de Andrade. O poema associa a aprendizagem do voo e da visão à liberdade. Leia o texto integral na página 1 do caderno oficial.', null, '["a expressão a \"vida toda\" é uma metáfora da tristeza do Melro.", "a noite escura simboliza a falta de perseverança do pássaro para alçar voo.", "as \"asas rotas\" do pássaro foram quebradas durante um voo noturno.", "o clarão da noite escura é uma metáfora do choro do pássaro.", "o voo do Melro é uma metáfora que representa a liberdade do pássaro."]'::jsonb, 'E', 'Alternativa E. No contexto indicado no enunciado, o voo do melro funciona como metáfora da liberdade e da superação de limitações. A leitura conecta o pássaro à luta por direitos civis, em vez de reduzir o poema à descrição literal de asas quebradas ou de uma noite triste. A interpretação deve considerar o conjunto do texto e a informação histórica apresentada.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 2, 'Literaturas', 'Sobre a canção "Um índio", de Caetano Veloso, marque a única alternativa que NÃO se apresenta como uma leitura possível:', 'Texto II: Um índio, de Caetano Veloso. Para a leitura literária da canção, consulte as páginas 1 e 2 do caderno oficial.', null, '["A canção apresenta um tom profético sobre a chegada de um índio ao Hemisfério Sul", "A canção valoriza um estereótipo da imagem do índio, em detrimento de sua sabedoria ambiental.", "A chegada do índio ocorrerá após todas as nações indígenas serem exterminadas.", "Na última estrofe, a revelação trazida pelo índio estabelece-se numa contradição entre ter sido desconhecida e, ao mesmo tempo, ser óbvia.", "O índio representado na canção traria consigo uma tecnologia e uma sabedoria superior em relação àquelas conhecidas até então."]'::jsonb, 'B', 'Alternativa B. A questão pede a interpretação que NÃO é adequada. A canção projeta a chegada de uma figura indígena portadora de conhecimentos e capacidades superiores às tecnologias conhecidas, valorizando sua sabedoria. Por isso, a afirmação de que haveria valorização de um estereótipo em detrimento dessa sabedoria contradiz a leitura proposta. O tom profético e o contraste entre revelação e obviedade são compatíveis com o texto.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 3, 'Literaturas', 'Nos trechos apresentados do conto "Amor", de Clarice Lispector, observa-se:', 'Texto III: Amor, de Clarice Lispector. Ana leva uma vida doméstica organizada. Durante uma viagem de bonde, ver um homem cego mascando chiclete provoca nela uma crise e altera sua percepção da realidade. O conto está nas páginas 2 e 3 do caderno oficial. As alternativas foram adaptadas para não repetir os trechos do conto.', null, '["Uma mulher do lar totalmente voltada para o trabalho de cuidado, plenamente satisfeita.", "Uma mulher inserida em uma vida matrimonial e familiar plena.", "Uma mulher plenamente satisfeita com o trabalho de cuidado e com a vida doméstica cotidiana.", "Uma mulher que se abala fortemente ao ver um deficiente visual mascando chicles.", "Uma mulher satisfeita como o rumo que a sua vida tomara, e com o seu cotidiano de mãe e esposa."]'::jsonb, 'D', 'Alternativa D. Ana aparentemente vive uma rotina doméstica estável, mas o encontro com o homem cego mascando chiclete provoca um forte abalo e muda sua percepção. Essa crise mostra que a personagem não está apenas satisfeita e acomodada ao cotidiano. As alternativas A, B, C e E descrevem plenitude ou satisfação sem considerar o desconforto e a ruptura presentes no conto.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 4, 'Literaturas', 'Considerando o conteúdo do texto IV, assinale a alternativa em que há o momento de "epifania" da personagem Ana, do conto de Clarice Lispector, no Texto III.', 'Texto IV: a epifania literária é uma revelação inesperada que muda a percepção da personagem a partir de uma situação cotidiana. No conto Amor, Ana vivencia essa mudança durante a viagem de bonde. Consulte os Textos III e IV na página 3 do caderno oficial. As alternativas descrevem as cenas, em vez de reproduzir o conto.', null, '["Ana grita e o condutor manda parar o bonde.", "Ana percebe o homem cego mascando chiclete.", "Os ovos se quebram e as gemas escorrem pela rede.", "Ana se recosta no banco para buscar conforto.", "Ana percebe o calor e os sons com maior intensidade."]'::jsonb, 'B', 'Alternativa B. A epifania ocorre quando Ana percebe o homem cego mascando chiclete: uma cena cotidiana desencadeia uma revelação e altera sua consciência. O grito, a queda dos ovos e a percepção intensificada do ambiente são acontecimentos ou efeitos associados à crise, mas a cena indicada em B identifica o instante que desencadeia essa mudança.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 5, 'Literaturas', 'No trecho acima (texto V), Simone de Beauvoir compara o trabalho de uma mulher do lar, dedicada aos afazeres domésticos e à criação dos filhos, ao mito de Sísifo, personagem da mitologia grega que foi condenado a repetir eternamente a tarefa de empurrar uma pedra até o topo de uma montanha. Considerando os textos III e V, assinale a alternativa correta:', 'Texto V: Simone de Beauvoir compara a repetição do trabalho doméstico ao suplício de Sísifo. Relacione essa reflexão à mudança de percepção de Ana no conto Amor. Os textos estão nas páginas 2 a 4 do caderno oficial.', null, '["A personagem Ana se mostra uma mulher frágil e cansada, que não consegue romper, em nenhum momento, com a monotonia de sua vida dedicada somente aos afazeres domésticos e à criação dos filhos.", "A personagem Ana, do conto \"Amor\", rompe, por um momento, o \"suplício de Sísifo\" de uma mulher do lar, no momento em que vê um deficiente visual mascando chicles e, a partir desse momento, começa a ver a realidade de outra forma.", "A personagem Ana, do conto \"Amor\", se dedica, com plena satisfação, aos afazeres domésticos e à criação dos filhos, sem sentir quaisquer tipos de incômodos ou inquietações.", "O mito de Sísifo diz respeito à personagem Ana, uma vez que ela não consegue romper com a vida cotidiana e com o trabalho de cuidado, e nem sentir, em nenhum momento, incômodos ou inquietações existenciais.", "O mito de Sísifo não diz nada a respeito da personagem Ana, uma mulher do lar totalmente dedicada ao trabalho de cuidado, cujo cotidiano é marcado por alegrias e contentamentos."]'::jsonb, 'B', 'Alternativa B. O mito de Sísifo representa uma tarefa que se repete sem uma conclusão definitiva, como os afazeres domésticos na reflexão de Beauvoir. Ao ver o homem cego, Ana rompe momentaneamente com a percepção rotineira da vida e passa a olhar a realidade de outra forma. Isso não significa que abandone definitivamente sua família ou elimine todo o trabalho doméstico; a ruptura é de percepção.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 6, 'Biologia', 'Leia o trecho da reportagem a seguir. As mudanças climáticas globais estão tornando os fungos patogênicos mais resistentes devido à aceleração de suas mutações genéticas e, no Brasil, a plantação de cacau é fortemente afetada pelo fungo Moniliophtera perniciosa, chamado comumente de vassoura de bruxa, que causa enegrecimento e morte do cacaueiro, causando grandes estragos nas lavouras e encarecendo os processos de controle dessa infestação. Com relação aos organismos considerados como fungos, pode-se afirmar que são um grupo formado por:', null, null, '["organismos eucariontes, autótrofos por absorção, que possuem grande importância pela produção de antibióticos e alimentos, mas que podem ser parasitas de plantas e animais, causando grandes prejuízos.", "organismos eucariontes, heterótrofos por absorção, que possuem grande importância pela produção de antibióticos e alimentos, mas que podem ser parasitas de plantas e animais, causando grandes prejuízos.", "organismos eucariontes, heterótrofos por absorção, que não possuem importância na produção de antibióticos e alimentos, e não são parasitas de plantas e animais, sem causar grandes prejuízos.", "organismos procariontes, heterótrofos por alimentação, que possuem grande importância pela produção de antibióticos e alimentos, mas que podem ser parasitas de plantas e animais, causando grandes prejuízos.", "organismos procariontes, heterótrofos por absorção, que possuem grande importância pela produção de antibióticos e alimentos, mas que podem ser parasitas de plantas e animais, causando grandes prejuízos."]'::jsonb, 'B', 'Alternativa B. Fungos são eucariontes, pois possuem células com núcleo organizado, e heterótrofos: não produzem alimento por fotossíntese. Obtêm nutrientes por absorção, geralmente após digestão extracelular. Podem ser usados na produção de alimentos e antibióticos, mas algumas espécies são parasitas de plantas ou animais. Portanto, são incorretas as alternativas que os classificam como procariontes ou autótrofos.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 7, 'Biologia', 'A Dra. Maria Beatriz de Barros Barreto, professora da UFRJ, participou do último Congresso Europeu de Algas, realizado em Brest, na França, em agosto de 2023, e descreveu que os pontos mais discutidos nesse congresso foram as alterações nas comunidades de algas marinhas, devido às mudanças climáticas. Vários pesquisadores no mundo verificaram a substituição de florestas marinhas formadas por algas pardas de grande porte, com mais de 1 metro de comprimento, por algas filamentosas formando tapetes de poucos centímetros de altura. O impacto dessa substituição ainda é incerto, mas pode ocorrer uma perda de espécies de algas pardas, que formam um grupo de organismos com representantes', null, null, '["unicelulares, com grande importância econômica (alimentar) e ecológica, muito comuns no litoral brasileiro.", "multicelulares, com grande importância econômica (alimentar) e ecológica, e que formam as chamadas \"florestas aquáticas\".", "unicelulares a multicelulares, com grande importância econômica (alimentar), e que formam as chamadas \"florestas aquáticas\".", "unicelulares a multicelulares, sem grande importância ecológica e econômica, muito comuns no litoral brasileiro.", "multicelulares, que não possuem grande importância econômica, muito comuns no litoral brasileiro."]'::jsonb, 'B', 'Alternativa B. As algas pardas são multicelulares e incluem formas de grande porte que estruturam florestas aquáticas. Esses ambientes oferecem abrigo, alimento e habitat para outros organismos e têm importância ecológica; espécies de algas pardas também têm aplicações alimentares e econômicas. As alternativas que atribuem unicelularidade ao grupo ou negam sua importância não correspondem à caracterização pedida.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 8, 'Biologia', 'Mudanças climáticas podem favorecer hospedeiros invertebrados e aumentar a ocorrência de doenças. Entre as doenças comuns em ecossistemas tropicais, quais são transmitidas por hospedeiros invertebrados, como artrópodes e moluscos?', null, null, '["dengue, leishmaniose, malária e cólera.", "malária, esquistossomose, leishmaniose e dengue.", "leishmaniose, ascaridíase, esquistossomose e malária.", "esquistossomose, cólera, amebíase e dengue.", "malária, esquistossomose, dengue e hepatite."]'::jsonb, 'B', 'Alternativa B. Malária é transmitida por mosquitos Anopheles; leishmaniose, por flebotomíneos; dengue, por mosquitos Aedes. Na esquistossomose, caramujos de água doce são hospedeiros intermediários e liberam cercárias que penetram pela pele humana em contato com água contaminada. Já cólera, amebíase e ascaridíase não dependem dos hospedeiros invertebrados indicados no enunciado para sua transmissão habitual.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 9, 'Biologia', 'O fóssil de Archaeopteryx lithographica é reconhecido como o primeiro registro de ave existente na natureza há milhões de anos atrás. No entanto, este organismo ainda apresentava uma mistura de características presentes em dinossauros Theropoda, mas ausentes nas aves atuais. É uma característica de Archaeopteryx lithographica também encontrada nas aves atuais', null, null, '["a cauda longa e número grande de vértebras caudais.", "as garras nos membros anteriores.", "as penas sem a presença de bárbulas.", "a presença de dentes.", "os ossos pneumáticos."]'::jsonb, 'E', 'Alternativa E. Entre as características listadas, os ossos pneumáticos aproximam Archaeopteryx das aves atuais. A presença de cavidades aéreas no esqueleto está associada ao sistema respiratório e à redução de massa de partes do esqueleto. Dentes, cauda óssea longa e garras nos membros anteriores são características mencionadas que não caracterizam o conjunto das aves atuais. O gabarito oficial seleciona E.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 10, 'Biologia', 'Os animais (Metazoa = animais) constituem um grupo com mais de 1,5 milhão de espécies descritas. Os metazoários (Metazoa) são muito diversificados e possuem características morfológicas, fisiológicas e evolutivas muito distintas. Em relação às características presentes nos distintos grupos animais, marque a opção que contém informações CORRETAS.', null, null, '["As águas-vivas possuem três folhetos embrionários (endoderme, mesoderme e ectoderme)", "Estrelas-do-mar, peixes, anfíbios, répteis, aves e mamífero são deuterostômios e todos possuem vértebras.", "Os artrópodes, anelídeos e peixes são animais protostômios.", "Sapos, pássaros, cobras e cães são deuterostômios, vertebrados e tetrápodes.", "Tilápias, sapos, jacarés, beija-flores, cavalos-marinhos e chimpanzés possuem maxilas e pulmão (ou bexiga natatória) derivado(a) do tubo digestório."]'::jsonb, 'D', 'Alternativa D. Sapos, pássaros, cobras e cães pertencem à linhagem dos vertebrados tetrápodes e são deuterostômios. A cobra continua sendo tetrápode na classificação evolutiva, apesar da perda secundária dos membros. Águas-vivas são diblásticas, não triblásticas; estrelas-do-mar são deuterostômios, mas não possuem vértebras; artrópodes e anelídeos são protostômios, enquanto peixes são deuterostômios.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Física', 'Considere g = 10,0 m/s², densidade da água do mar aproximadamente igual a 1,0 g/cm³ e pressão atmosférica igual a 1,0 × 10⁵ N/m². A profundidade no mar que corresponde a uma pressão total de 2,0 atm é de aproximadamente:', 'Nas questões de Física, considere g = 10,0 m/s² e a pressão atmosférica na superfície igual a 1,0 atm.', null, '["10,0 m", "20,0 m", "100,0 m", "200,0 m", "2,0 m"]'::jsonb, 'A', 'Alternativa A. A pressão total em uma profundidade h é P = P_atm + ρgh. Como a pressão total é 2 atm e a superfície está a 1 atm, a contribuição da água é 1 atm = 10⁵ Pa. Converta a densidade: 1 g/cm³ = 1000 kg/m³. Logo, h = 10⁵/(1000 × 10) = 10 m. Usar diretamente 2 atm na parcela ρgh desconsideraria a pressão atmosférica.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 12, 'Física', 'Considere um dispositivo que consiste em um tubo de maior área e uma parede central contendo um pequeno orifício que deixa a passagem de fluxo de ar para outro lado somente em um sentido. Sabe-se que o fluxo de ar é incompressível, que a velocidade do som no ar é de aproximadamente 340, 0 m/s, que o diâmetro do orifício é de 1, 0 mm² e que a velocidade do fluxo de ar no orifício é o dobro da velocidade do som no ar. O valor da velocidade do fluxo de ar antes do orifício numa área de 10, 0 cm² é de', 'Na prova, o enunciado usa a expressão diâmetro do orifício com unidade mm². Foi preservada a redação oficial; o valor de 1,0 mm² é usado como área no cálculo da continuidade.', null, '["0, 68 m/s", "6, 80 m/s", "0, 34 m/s", "3, 40 m/s", "0, 17 m/s"]'::jsonb, 'A', 'Alternativa A. Para fluxo incompressível, a continuidade dá A1v1 = A2v2. No orifício, v2 = 2 × 340 = 680 m/s. A área maior é 10 cm² = 1000 mm²; a área do orifício indicada na prova é 1 mm². Assim, v1 = 680 × 1/1000 = 0,68 m/s. O enunciado chama a medida em mm² de diâmetro, mas mm² é unidade de área: a resolução compatível com o gabarito usa essa medida como área.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 13, 'Física', 'Em relação ao microscópio óptico e à luneta astronômica, assinale a alternativa CORRETA.', null, null, '["Em ambos os instrumentos há uma lente convergente e uma lente divergente.", "A imagem da primeira lente na qual passa a luz é virtual e reduzida nos dois instrumentos.", "Em ambos os instrumentos, a imagem final é real e ampliada.", "Em ambos, os objetos observados devem ficar próximo a uma das lentes.", "Um serve para observar objetos pequenos e próximos e o outro para objetos grandes e distantes."]'::jsonb, 'E', 'Alternativa E. O microscópio permite observar objetos pequenos e próximos; a luneta astronômica é usada para objetos distantes. Nos modelos ópticos usuais com objetiva e ocular convergentes, a objetiva produz uma imagem intermediária real, e a ocular permite a observação de uma imagem final virtual. Não se pode afirmar que a imagem final é real nos dois instrumentos, nem que os objetos observados precisam estar próximos em ambos.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 14, 'Física', 'Em relação às ondas sonoras, assinale a alternativa CORRETA.', 'Gabarito definitivo após recursos: as alternativas C e E são aceitas nesta questão.', null, '["O som se propaga no vácuo.", "A velocidade do som é maior nos gases do que nos sólidos.", "A escala da intensidade sonora é linear.", "Sons graves são de alta frequência e sons agudos de baixa frequência.", "O som sofre refração, o que permite criar lentes acústicas."]'::jsonb, 'C/E', 'Alternativas C ou E, conforme o gabarito definitivo após recursos. A alternativa E é sustentada pela refração do som quando sua velocidade de propagação muda, fenômeno utilizado em lentes acústicas. Para interpretar C, distinga a intensidade física I, medida em W/m², do nível sonoro em decibéis: β = 10 log₁₀(I/I₀), que é logarítmico. O gabarito também aceita C, mas isso não significa que a escala em decibéis seja linear. O som exige meio material; sons graves têm menor frequência, e agudos, maior.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Física', 'Em relação aos processos de propagação do calor, assinale a alternativa CORRETA.', 'Gabarito definitivo após recursos: as alternativas B e C são aceitas nesta questão.', null, '["A condução ocorre entre uma superfície sólida e o vácuo.", "A radiação se propaga entre dois sólidos.", "A convecção ocorre entre uma superfície sólida e um fluido livre.", "A condução ocorre entre dois fluidos livres.", "A convecção ocorre entre um fluido livre e o vácuo."]'::jsonb, 'B/C', 'Alternativas B ou C, conforme o gabarito definitivo após recursos. A radiação térmica transmite energia por ondas eletromagnéticas e pode ocorrer entre dois sólidos, inclusive separados por vácuo. A convecção envolve o movimento de um fluido e é usada para descrever a troca de calor entre uma superfície e o fluido ao redor, como em C. Condução depende de interações materiais e não transmite calor através de um espaço vazio; convecção também exige um fluido. As duas respostas aceitas devem ser consideradas corretas na pontuação.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'História', 'Os textos de Paulina Chiziane e Ngugi wa Thiong’o denunciam o apagamento de línguas, crenças, memórias e identidades pelo colonialismo. Chiziane convoca ao reconhecimento das raízes; Thiong’o discute a destruição da confiança dos povos em sua própria cultura. Marque a alternativa correta sobre a relação dos textos com a dominação imperialista da África:', null, null, '["A denúncia à dominação cultural apresentada nos dois textos não tem correspondência com a realidade, pois a história do imperialismo na África foi baseada na dominação econômica e política.", "O poema de Paulina Chiziane e a obra acadêmica de Ngugi Wa Thiongò são expressões atuais de resistência cultural dos povos africanos ao colonialismo e ao imperialismo, representados pelos europeus.", "Os textos apresentam pontos de vista opostos sobre a história de dominação da África, já que, diferente do Texto II, o Texto I destaca a valorização da cultura e da religiosidade africanas pelas nações que invadiram o continente.", "A convocação para a luta em defesa da liberdade proposta nos dois textos é um recurso literário, já que historicamente os povos africanos mantiveram-se passivos à exploração colonial no continente.", "Os textos descrevem a cultura africana anterior às invasões coloniais e imperialistas, destacando suas características históricas naquele período, como a ausência de crenças, línguas e culturas por parte daqueles povos."]'::jsonb, 'B', 'Alternativa B. Ambos os textos denunciam a dimensão cultural do colonialismo e do imperialismo, como o apagamento de identidades, crenças e línguas. A produção de escritores africanos que reafirma essas referências funciona como resistência cultural. A dominação não foi apenas econômica e política, e os povos africanos não permaneceram passivos: também resistiram e defenderam suas memórias e formas de vida.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'História', 'Luís Gama, Adelina e Francisco José do Nascimento, conhecido como Dragão do Mar, atuaram de diferentes formas contra a escravidão: defesa jurídica, circulação de informações e recusa ao transporte de escravizados. Sobre essas personagens e sua relação com o fim da escravidão, é correto afirmar que:', null, null, '["a abolição foi resultado da luta das classes mais ricas, insatisfeitas com a falta de mão de obra assalariada e a queda da venda de produtos.", "o fim da escravidão foi um movimento organizado em todo Brasil e que seguia a mesma lógica de violência contra os senhores de escravos.", "a escravidão mostrava sinais de desgaste, o que fez surgir o movimento abolicionista que envolvia homens e mulheres, ex-escravos e pessoas negras.", "o fim da escravidão foi resultado da liderança de profissionais liberais que usavam os ex-escravos para os atos violentos contra os proprietários.", "o efeito das revoltas e fugas de escravos foi frágil, contribuindo para o fortalecimento de ações de repressão pela manutenção da escravidão."]'::jsonb, 'C', 'Alternativa C. A luta abolicionista envolveu grupos e estratégias variados, incluindo pessoas negras, mulheres, homens livres e ex-escravizados. Luís Gama atuou na defesa jurídica, Adelina forneceu informações e Dragão do Mar recusou o transporte de escravizados. Esses exemplos mostram a participação de sujeitos diversos e impedem reduzir a abolição a uma iniciativa exclusiva das elites ou a uma única estratégia nacional.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'História', 'Em 1808, a família real portuguesa e sua corte transferiram-se para o Brasil, transportando pessoas e bens públicos e particulares. Sobre o significado desse evento para a história do Brasil, assinale a alternativa correta:', null, null, '["A cidade do Rio de Janeiro não foi a grande beneficiária da imigração dos Bragança, mesmo com a ocupação de suas casas, pois as demais capitanias brasileiras foram as que ganharam em infraestruturas urbanas e instituições.", "Os interesses regionais e os movimentos separatistas do Rio Grande do Sul e Pernambuco foram vitoriosos ao oferecer resistência à instalação da Corte portuguesa no Rio de Janeiro a partir de 1808.", "As relações com a Inglaterra pioraram com o fechamento dos portos às nações amigas e ao comércio dos navios britânicos, e a preferência portuguesa pelos artigos de luxo provenientes da França.", "A transformação da colônia brasileira no centro do Império Português e as mudanças políticas, sociais e culturais processadas, iniciaram a modernização do país, gerando as bases para sua independência.", "A vinda da família real para o Rio de Janeiro foi motivada pelo apoio dos Holandeses que há muito ocupavam o nordeste brasileiro e ofereciam a estabilidade necessária para instalação da monarquia portuguesa."]'::jsonb, 'D', 'Alternativa D. A transferência da corte em 1808 transformou o Rio de Janeiro em sede do Império Português e trouxe instituições, mudanças administrativas e transformações econômicas e culturais. A abertura dos portos e a elevação do Brasil a Reino Unido contribuíram para alterar sua posição colonial e criar condições para a independência. Isso não significa ausência de conflitos ou benefícios distribuídos igualmente entre as regiões.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 19, 'História', 'Uma entrevista de Eurídice Figueiredo relaciona a violência da escravidão à violência racial atual. A imagem de apoio mostra manifestantes em Saint Louis, nos Estados Unidos, protestando contra a violência policial. Sobre esse tema, marque a alternativa correta:', null, null, '["Comparar os torturadores e traficantes de escravos com policiais é uma forma de enfraquecer a luta entre brancos e negros, reforçando o racismo atual.", "As explosões de raiva e ressentimento dos movimentos sociais não se justificam na contemporaneidade, uma vez que a justiça já criminaliza o racismo.", "As manifestações de rua dos movimentos sociais são extremistas, o que leva os policiais a agirem de forma violenta, como os antigos traficantes de escravos.", "A morte de pessoas negras ainda hoje é resultado da recusa da população negra de se integrar à sociedade atual, demonstrando que a história se repete.", "As agressões e violências contra a população negra se renovam, e acabam por fortalecer o debate contra o racismo e a valorização da cultura e ancestralidade negras."]'::jsonb, 'E', 'Alternativa E. O texto e a imagem relacionam formas históricas de violência racial à sua persistência no presente. As agressões renovam o debate sobre racismo, direitos e valorização das culturas e ancestralidades negras. A criminalização do racismo não elimina automaticamente práticas discriminatórias; tampouco a violência pode ser justificada por uma suposta recusa das vítimas em integrar-se à sociedade.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 20, 'História', 'O romance A ilha sob o mar, de Isabel Allende, aborda a colonização e a escravidão no território do Haiti. O país tornou-se independente após um movimento revolucionário inserido no contexto internacional. Sobre o movimento de independência do Haiti, assinale a alternativa correta:', null, null, '["Deste movimento rebelde, resultou o único estado oriundo de uma insurreição de escravizados e o primeiro país da América a abolir a escravidão;", "Ao lado dos cativos, os atores principais foram as elites francesas formadas por proprietários e administradores;", "O evento repercutiu diretamente na América Portuguesa, gerou uma série de rebeliões vitoriosas protagonizadas por escravizados africanos e indígenas.", "O movimento revolucionário do Haiti foi fortemente influenciado pelos ideais da Revolução Francesa e recebeu o apoio das tropas napoleônicas.", "O processo revolucionário se expandiu rapidamente para além dos limites da ilha, favorecendo concomitantemente a libertação dos escravizados da América do Norte."]'::jsonb, 'A', 'Alternativa A. A independência do Haiti, proclamada em 1804, resultou de uma revolução protagonizada por escravizados e marcou a formação de um Estado independente a partir dessa insurreição. O Haiti foi o primeiro país independente das Américas a abolir a escravidão. O processo dialogou com a Revolução Francesa, mas as tropas enviadas por Napoleão tentaram restabelecer o controle francês, em vez de apoiar a emancipação.' from public.exams where slug='pism-ii-2025-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

commit;

select e.slug, count(q.id) as quantidade_questoes from public.exams e left join public.questions q on q.exam_id=e.id where e.slug in ('pism-ii-2025-dia-1','pism-ii-2025-dia-2') group by e.slug order by e.slug;
